//! Per-camera baseline exposure as Adobe applies it.
//!
//! Adobe DNG Converter writes a BaselineExposure into every DNG it makes;
//! Camera Raw and Lightroom render proprietary RAWs with that value. It is
//! a per-model constant for most cameras (0.35 EV for Sony's α7 III/IV,
//! 0.2 for Nikon's Z 6, −0.5 for many compacts); for Fujifilm it is the
//! file's RawExposureBias (ISO dependent) plus a per-model constant. The
//! table was generated by notes: scripts/reference/adobe_baseline_table.py from
//! 1,638 raw.pixls.us samples (688 Adobe camera models) converted with
//! Adobe DNG Converter 18.7, plus probe runs that converted copies of one
//! file per model with a single metadata field patched
//! (notes: benchmark-results/adobe-baseline-capture-modes.json):
//!
//! - EXIF ISO: extended low ISOs (Olympus/Pentax/Nikon "L", Canon 50) are
//!   up to a stop darker; Canon's pulled intermediate ISOs (160, 320, …)
//!   about a third of a stop on older bodies; Sony and Nikon bodies change
//!   at their second gain stage.
//! - Canon ColorData SpecularWhiteLevel (lower at ISO 100 and for pulled
//!   ISOs on bodies since 2010): `min(0, log2((white − black) /
//!   (reference white − black)))`, exact to 0.01 EV in the sweeps.
//! - Canon highlight tone priority: its own ISO table (mostly +1 EV, the
//!   newer bodies use the table of half the ISO).
//! - Canon sRAW/mRAW: own tables on the older bodies.
//! - Image shape: Phase One Sensor+ binning, Sony α1 II lossless
//!   compressed Medium/Small (four-channel files).

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Kind {
    /// Adobe's BaselineExposure for the model.
    Fixed,
    /// Fujifilm: add the file's RawExposureBias negated.
    OffsetToFujifilmBias,
    /// Olympus / OM System: subtract `log2(SensorCalibration / 256)` (the
    /// gain the camera applied; 512 at extended low ISO).
    OlympusCalibration,
}

/// Which files of a camera a rule applies to.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Variant {
    Any,
    /// Canon sRAW1 (mRAW) and sRAW2 (sRAW) files.
    CanonSRaw,
    /// Reduced-size captures (binning), by the decoded width.
    WidthAtMost(u32),
    /// Reduced-resolution files stored with several colour channels per
    /// pixel (Sony lossless compressed Medium/Small, YCbCr).
    MultiChannel,
    /// Files with this (lower-case) extension: Hasselblad CFV-50c 3FR
    /// captures and Phocus FFF exports get different Adobe baselines.
    Extension(&'static str),
}

/// (ISO min, ISO max, EV delta to the base).
type IsoRun = (u32, u32, f32);

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rule {
    /// Adobe's value for the plain capture (the cap of the white-level term).
    pub base: f32,
    pub kind: Kind,
    /// Deltas by EXIF ISO; ISOs outside every run add nothing.
    pub iso: &'static [IsoRun],
    /// Canon: the ColorData white level at which the base applies; 0 = no
    /// white-level term.
    pub white_reference: f32,
    /// Deltas by ISO when Canon's highlight tone priority or Pentax's
    /// highlight correction is on (replace `iso`); empty = no effect.
    pub highlight_tone_priority: &'static [IsoRun],
}

/// What the renderer knows about the file.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Capture {
    pub iso: Option<u32>,
    /// Fujifilm RawExposureBias of the RAF.
    pub fujifilm_bias: Option<f32>,
    pub canon: Option<crate::capture_info::CanonCapture>,
    /// Pentax highlight correction (DynamicRangeExpansion); Canon's
    /// highlight tone priority is in `canon`.
    pub pentax_highlight_correction: bool,
    /// Olympus / OM System SensorCalibration gain (256 = nominal).
    pub olympus_calibration: Option<u16>,
    /// Decoded width and whether the file has more than one colour channel
    /// per pixel; read only for cameras with a size- or channel-dependent rule.
    pub width: Option<u32>,
    pub multi_channel: bool,
    /// Fujifilm dynamic range of the capture in percent (100, 230, 400).
    pub fujifilm_dynamic_range: Option<u32>,
    /// Lower-case file extension, zero-padded (for `Variant::Extension`).
    pub extension: [u8; 4],
}

/// A file extension in the form `Capture::extension` keeps it.
pub fn extension_key(path: &str) -> [u8; 4] {
    let mut key = [0u8; 4];
    if let Some((_, ext)) = path.rsplit_once('.') {
        for (slot, byte) in key.iter_mut().zip(ext.bytes()) {
            *slot = byte.to_ascii_lowercase();
        }
    }
    key
}

/// Fujifilm SuperCCD SR and EXR bodies whose Adobe baseline includes the
/// dynamic-range boost: DNG Converter's BaselineExposure is the DR100 value
/// plus log2(DR / 100), and Camera Raw extends the white level by the same
/// factor or more (`fujifilm_white_extension_ev`). Their measured rows hold
/// the DR100 value (samples were DR400: S3 Pro, S5 Pro 3.5, F700, F600EXR
/// 3.0).
pub const FUJIFILM_DR_BASELINE_MODELS: &[&str] = &[
    "FinePix F600EXR",
    "FinePix F700",
    "FinePix S3Pro",
    "FinePix S5Pro",
];

/// EV of the white level Camera Raw adds when rendering such a capture.
/// EXR bodies: the dynamic-range boost itself (F600EXR at DR 400: midtones
/// +1.79 → −0.18 EV against Camera Raw). SuperCCD SR bodies record the
/// low-sensitivity R photodiodes, and Camera Raw's white sits at their
/// saturation instead, a fixed number of stops above the S photodiodes'
/// (fitted to Camera Raw's renders of one DR 400 file each: S3 Pro 3.7,
/// S5 Pro 3.85, F700 3.35 stops).
pub fn fujifilm_white_extension_ev(make: &str, model: &str, dynamic_range: Option<u32>) -> f32 {
    let boost = fujifilm_dynamic_range_ev(make, model, dynamic_range);
    const SUPERCCD_SR_STOPS: &[(&str, f32)] = &[
        ("FinePix F700", 3.35),
        ("FinePix S3Pro", 3.8),
        ("FinePix S5Pro", 3.8),
    ];
    match SUPERCCD_SR_STOPS
        .iter()
        .find(|(m, _)| m.eq_ignore_ascii_case(model))
    {
        Some((_, stops)) if boost > 0.0 => *stops,
        _ => boost,
    }
}

/// Adobe's baseline boost for such a capture: log2(DR / 100) (0 elsewhere).
pub fn fujifilm_dynamic_range_ev(make: &str, model: &str, dynamic_range: Option<u32>) -> f32 {
    let listed = make.eq_ignore_ascii_case("fujifilm")
        && FUJIFILM_DR_BASELINE_MODELS
            .iter()
            .any(|m| m.eq_ignore_ascii_case(model));
    match dynamic_range {
        Some(dr) if listed && (100..=1600).contains(&dr) => (dr as f32 / 100.0).log2(),
        _ => 0.0,
    }
}

/// Olympus / OM System bodies without a table entry: Adobe's value is
/// `0.5 − log2(calibration / 256)` on every interchangeable-lens body
/// sampled (compacts differ: TG 1.03, XZ-2 1.53).
pub const OLYMPUS_CALIBRATION_BASE: f32 = 0.5;

type Entry = (&'static str, &'static str, Variant, Rule);

