/// EV to add so rawler's white level renders like Adobe's (see
/// `ADOBE_WHITE_EV`); 0 for cameras without a measured difference.
pub fn adobe_white_correction(make: &str, model: &str, iso: Option<u32>) -> f32 {
    let iso = iso.unwrap_or(0);
    ADOBE_WHITE_EV
        .iter()
        .filter(|(m, n, _, _, _)| m.eq_ignore_ascii_case(make) && n.eq_ignore_ascii_case(model))
        .find(|(_, _, low, high, _)| (*low..=*high).contains(&iso))
        .map_or(0.0, |entry| entry.4)
}

/// Whether the white-level table has the camera.
pub fn has_white_correction(make: &str, model: &str) -> bool {
    ADOBE_WHITE_EV
        .iter()
        .any(|(m, n, _, _, _)| m.eq_ignore_ascii_case(make) && n.eq_ignore_ascii_case(model))
}

fn entries(make: &str, model: &str) -> impl Iterator<Item = &'static Entry> {
    let (make, model) = (make.to_ascii_lowercase(), model.to_ascii_lowercase());
    let matches = move |(m, n, _, _): &&'static Entry| {
        m.eq_ignore_ascii_case(&make) && n.eq_ignore_ascii_case(&model)
    };
    let measured: Vec<&'static Entry> = ADOBE_BASELINE_MEASURED
        .iter()
        .filter(matches.clone())
        .collect();
    // A measured row replaces every generated row of the model.
    let generated: Vec<&'static Entry> = if measured.is_empty() {
        ADOBE_BASELINE.iter().filter(matches).collect()
    } else {
        Vec::new()
    };
    measured.into_iter().chain(generated)
}

/// Whether the table has a rule for the camera.
pub fn has_entry(make: &str, model: &str) -> bool {
    entries(make, model).next().is_some()
}

/// Whether the camera has a rule that needs the decoded image shape.
pub fn needs_image_shape(make: &str, model: &str) -> bool {
    entries(make, model).any(|(_, _, variant, _)| {
        matches!(variant, Variant::WidthAtMost(_) | Variant::MultiChannel)
    })
}

fn run_delta(runs: &[IsoRun], iso: Option<u32>) -> Option<f32> {
    let iso = iso?;
    runs.iter()
        .find(|(min, max, _)| *min <= iso && iso <= *max)
        .map(|(_, _, delta)| *delta)
}

/// Adobe's baseline exposure for a camera and capture; `None` for unknown
/// cameras (and for Fujifilm models whose file lacks the bias).
pub fn adobe_baseline(make: &str, model: &str, capture: &Capture) -> Option<f32> {
    let sraw = capture.canon.is_some_and(|c| c.sraw_quality > 0);
    let specific = entries(make, model).find(|(_, _, variant, _)| match variant {
        Variant::Any => false,
        Variant::CanonSRaw => sraw,
        Variant::WidthAtMost(limit) => capture.width.is_some_and(|w| w <= *limit),
        Variant::MultiChannel => capture.multi_channel,
        Variant::Extension(ext) => capture.extension == extension_key(&format!(".{ext}")),
    });
    let Some((_, _, _, rule)) =
        specific.or_else(|| entries(make, model).find(|(_, _, v, _)| *v == Variant::Any))
    else {
        let lower_make = make.to_ascii_lowercase();
        let calibration = capture.olympus_calibration?;
        return (lower_make == "olympus" || lower_make.starts_with("om "))
            .then(|| OLYMPUS_CALIBRATION_BASE - (calibration as f32 / 256.0).log2());
    };
    let mut value = match rule.kind {
        Kind::Fixed => rule.base,
        Kind::OffsetToFujifilmBias => rule.base - capture.fujifilm_bias?,
        Kind::OlympusCalibration => {
            rule.base
                - capture
                    .olympus_calibration
                    .map_or(0.0, |calibration| (calibration as f32 / 256.0).log2())
        }
    };
    let htp = (capture.canon.is_some_and(|c| c.highlight_tone_priority)
        || capture.pentax_highlight_correction)
        && !rule.highlight_tone_priority.is_empty();
    value += if htp {
        // Measured with the flag on at every ISO; ISOs outside the runs
        // (and runs that only list the ISO range) fall back to one stop.
        run_delta(rule.highlight_tone_priority, capture.iso).unwrap_or(1.0)
    } else {
        run_delta(rule.iso, capture.iso).unwrap_or(0.0)
    };
    if rule.white_reference > 0.0
        && let Some(canon) = capture.canon
        && let (Some(black), Some(white)) = (canon.black, canon.specular_white)
        && (white as f32) > black
        && rule.white_reference > black
    {
        value += ((white as f32 - black) / (rule.white_reference - black))
            .log2()
            .min(0.0);
    }
    value += fujifilm_dynamic_range_ev(make, model, capture.fujifilm_dynamic_range);
    // Adobe writes two decimals; rounding keeps renders byte-identical when a
    // formula lands on the old table value (and turns −0.0 into 0.0).
    Some((value * 100.0).round() / 100.0 + 0.0)
}

#[cfg(test)]
mod tests {
    use super::{Capture, adobe_baseline, extension_key, has_entry, needs_image_shape};
    use crate::capture_info::CanonCapture;

    fn canon(iso: u32, black: f32, white: u32, htp: bool, sraw: u16) -> Capture {
        Capture {
            iso: Some(iso),
            canon: Some(CanonCapture {
                black: Some(black),
                specular_white: Some(white),
                highlight_tone_priority: htp,
                sraw_quality: sraw,
            }),
            ..Capture::default()
        }
    }

    fn close(a: Option<f32>, b: f32) -> bool {
        a.is_some_and(|a| (a - b).abs() < 0.02)
    }

    #[test]
    fn measured_rows_replace_generated_ones() {
        let at = |iso| Capture {
            iso: Some(iso),
            ..Capture::default()
        };
        // D800 samples were all at Lo 1: normal ISOs get the D800E value.
        assert!(close(adobe_baseline("Nikon", "D800", &at(400)), 0.35));
        assert!(close(adobe_baseline("Nikon", "D800", &at(50)), -0.65));
        // CRW: ISO 100 is 0.36 EV above the other ISOs.
        assert!(close(adobe_baseline("Canon", "EOS 10D", &at(100)), -0.14));
        assert!(close(adobe_baseline("Canon", "EOS 300D", &at(400)), -0.5));
        // Models the generated table lacked.
        assert!(close(
            adobe_baseline("Panasonic", "DMC-TZ80", &at(100)),
            -0.5
        ));
        assert!(has_entry("Pentax", "*ist D"));
        // R5 Mark II: highlight tone priority adds a stop.
        let mut htp = canon(640, 512.0, 14888, true, 0);
        assert!(close(adobe_baseline("Canon", "EOS R5 Mark II", &htp), 1.52));
        htp.canon.as_mut().unwrap().highlight_tone_priority = false;
        assert!(close(adobe_baseline("Canon", "EOS R5 Mark II", &htp), 0.52));
    }

    #[test]
    fn known_cameras_follow_adobe() {
        let plain = Capture {
            iso: Some(400),
            ..Capture::default()
        };
        assert_eq!(adobe_baseline("Sony", "ILCE-7M3", &plain), Some(0.35));
        // GFX 50R: −RawExposureBias − 0.5 (DNG Converter: bias −0.72 → 0.22).
        let gfx = Capture {
            fujifilm_bias: Some(-0.72),
            ..Capture::default()
        };
        assert!(close(adobe_baseline("Fujifilm", "GFX 50R", &gfx), 0.22));
        assert_eq!(adobe_baseline("Fujifilm", "GFX 50R", &plain), None);
        assert_eq!(adobe_baseline("Nobody", "Camera", &plain), None);
    }

    #[test]
    fn canon_white_level_lowers_the_value_until_the_reference_white() {
        // 550D (DNG Converter sweep): ISO 100 file, white 12279 → −0.34;
        // 8000 → −1.12; 15000 and above → 0.00.
        assert!(close(
            adobe_baseline("Canon", "EOS 550D", &canon(100, 2047.75, 12279, false, 0)),
            -0.34
        ));
        assert!(close(
            adobe_baseline("Canon", "EOS 550D", &canon(100, 2047.75, 8000, false, 0)),
            -1.12
        ));
        assert!(close(
            adobe_baseline("Canon", "EOS 550D", &canon(1600, 2047.75, 16383, false, 0)),
            0.0
        ));
        // Highlight tone priority adds a stop on top of the white-level term.
        assert!(close(
            adobe_baseline("Canon", "EOS 1200D", &canon(200, 2045.0, 12279, true, 0)),
            0.66
        ));
    }

    #[test]
    fn canon_iso_tables_and_sraw() {
        // 7D: ISO 100 −0.21, pulled ISO 160 −0.34, ISO 400 0.00.
        assert!(close(
            adobe_baseline("Canon", "EOS 7D", &canon(100, 2047.0, 12279, false, 0)),
            -0.21
        ));
        assert!(close(
            adobe_baseline("Canon", "EOS 7D", &canon(160, 2047.0, 12279, false, 0)),
            -0.34
        ));
        assert!(close(
            adobe_baseline("Canon", "EOS 7D", &canon(400, 2047.0, 12279, false, 0)),
            0.0
        ));
        // 5D Mark II: sRAW files sit 0.25 EV above the full RAW table.
        assert!(close(
            adobe_baseline(
                "Canon",
                "EOS 5D Mark II",
                &canon(800, 1024.0, 15312, false, 0)
            ),
            0.40
        ));
        assert!(close(
            adobe_baseline(
                "Canon",
                "EOS 5D Mark II",
                &canon(800, 1024.0, 16383, false, 1)
            ),
            0.65
        ));
    }

    #[test]
    fn olympus_calibration_and_pentax_highlight_correction() {
        let om5 = Capture {
            olympus_calibration: Some(290),
            ..Capture::default()
        };
        assert!(close(
            adobe_baseline("OM Digital Solutions", "OM-5", &om5),
            0.32
        ));
        // Compacts have their own constant (TG-6: 1.04).
        let tg6 = Capture {
            olympus_calibration: Some(372),
            ..Capture::default()
        };
        assert!(close(adobe_baseline("Olympus", "TG-6", &tg6), 0.50));
        let low_iso = Capture {
            olympus_calibration: Some(512),
            ..Capture::default()
        };
        assert!(close(
            adobe_baseline("Olympus", "E-M10 Mark III", &low_iso),
            -0.5
        ));
        // Unknown Olympus body: the formula still applies.
        assert!(close(adobe_baseline("Olympus", "E-M99", &low_iso), -0.5));
        let plain = Capture {
            iso: Some(125),
            ..Capture::default()
        };
        assert!(close(adobe_baseline("Pentax", "K-1 Mark II", &plain), -0.5));
        let corrected = Capture {
            pentax_highlight_correction: true,
            ..plain
        };
        assert!(close(
            adobe_baseline("Pentax", "K-1 Mark II", &corrected),
            0.5
        ));
    }

    #[test]
    fn size_and_channel_variants() {
        assert!(needs_image_shape("Phase One", "P65+"));
        assert!(!needs_image_shape("Sony", "ILCE-7M3"));
        let full = Capture {
            width: Some(9036),
            ..Capture::default()
        };
        let binned = Capture {
            width: Some(4544),
            ..Capture::default()
        };
        assert!(close(adobe_baseline("Phase One", "P65+", &full), 1.49));
        assert!(close(adobe_baseline("Phase One", "P65+", &binned), 0.49));
        let four = Capture {
            multi_channel: true,
            ..Capture::default()
        };
        assert!(close(adobe_baseline("Sony", "ILCE-1M2", &four), 0.05));
        assert!(close(
            adobe_baseline("Sony", "ILCE-1M2", &Capture::default()),
            0.15
        ));
    }

    #[test]
    fn extension_variant_separates_3fr_from_fff() {
        let three_fr = Capture {
            extension: extension_key("/x/B0000420.3FR"),
            ..Capture::default()
        };
        let fff = Capture {
            extension: extension_key("/x/B0000420.fff"),
            ..Capture::default()
        };
        assert!(close(
            adobe_baseline("Hasselblad", "CFV-50c", &three_fr),
            0.26
        ));
        assert!(close(adobe_baseline("Hasselblad", "CFV-50c", &fff), -0.25));
        assert_eq!(extension_key("no_extension"), [0; 4]);
    }
}
